SELECT status, COUNT(*) AS order_count
FROM orders
GROUP BY status;

SELECT ROUND(AVG(amount_minor) / (
    SELECT CAST(value AS REAL)
    FROM shop_meta
    WHERE key = 'minor_units_per_dollar'
), 2) AS average_refund_dollars
FROM refunds;

