SELECT ROUND(100.0 * COUNT(CASE WHEN order_id IS NULL THEN 1 END)
             / NULLIF(COUNT(*), 0), 2) AS percentage_without_order
FROM tickets;

SELECT COALESCE(SUM(
    o.shipping_minor + COALESCE((
        SELECT SUM(oi.quantity * oi.unit_price_minor)
        FROM order_items AS oi
        WHERE oi.order_id = o.id
    ), 0)
), 0) / 100.0 AS total_charge_dollars
FROM orders AS o
WHERE o.status = 'pending_payment';

